"""Render a static, evidence-backed audit site. No unverified scores are promoted."""
import html
import json
from pathlib import Path
import markdown

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / 'docs'
STYLE = '''
:root{color-scheme:light;--ink:#172d36;--muted:#48616b;--line:#d5e0e2;--accent:#087e83}*{box-sizing:border-box}body{margin:0;background:#f3f7f7;color:var(--ink);font:16px/1.65 system-ui,sans-serif}header{background:#122f39;color:white;padding:24px max(5%,calc((100% - 1200px)/2))}header a{color:#acedef}nav{display:flex;gap:24px;flex-wrap:wrap}main{max-width:1200px;margin:auto;padding:36px 24px 70px}h1{font-size:clamp(2rem,4vw,3.3rem);line-height:1.15;letter-spacing:-.04em}h2{margin-top:2rem;line-height:1.3}a{color:#08666b;text-underline-offset:3px}a:focus-visible{outline:3px solid #ca6e20}p{max-width:90ch}.eyebrow{font-size:12px;letter-spacing:.15em;text-transform:uppercase}.banner{border-left:6px solid #ab3434;background:#fff1ed;padding:22px 28px;margin:24px 0}.banner strong{color:#8e2020;font-size:1.3rem}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.card{padding:22px;background:white;border:1px solid var(--line);border-radius:12px}.card b{font-size:2rem;display:block}.scroll{overflow-x:auto;background:white;border:1px solid var(--line);border-radius:12px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:16px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{background:#e5f0ef}td small{display:block;max-width:32ch;overflow-wrap:anywhere;color:var(--muted)}code{overflow-wrap:anywhere;font-size:.87em}pre{white-space:pre-wrap;background:#e5eeee;padding:18px}footer{border-top:1px solid var(--line);padding:22px;color:var(--muted)}.button{display:inline-block;background:var(--accent);color:white;padding:10px 16px;border-radius:6px;text-decoration:none;margin:6px 8px 6px 0}.muted{color:var(--muted)}li{margin-bottom:8px}
'''


def page(title, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · GEMS Evidence Lab</title><style>{STYLE}</style></head><body><header><div class="eyebrow">WBGGEMSDOE3 / GEMS Evidence Lab</div><nav aria-label="Main"><a href="index.html">Decision & nine-site audit</a><a href="executive-summary.html">Executive summary & submission guide</a><a href="research.html">Scientific review</a><a href="sources.json">Source pins</a></nav></header><main>{body}</main><footer>Snapshot: 2026-10-26 · No competition upload performed · Evidence over optimism</footer></body></html>'''


def build():
    audit = json.loads((DOCS / 'audit.json').read_text())
    inputs = json.loads((ROOT / 'research/input_manifest.json').read_text())
    rows = ''
    for item in inputs[:9]:
        name = item['id']; r = audit['rows'][name]
        url = f"https://github.com/{item['repo']}/blob/{item['ref']}/{item['path']}?raw=true"
        file = Path(item['path']).name
        rows += f'''<tr><td><strong>{name}</strong>{'<small>Highest historical claim in supplied focus list; not confirmed</small>' if name=='GEMSDOE32' else ''}</td><td><a href="{html.escape(url)}">Historical TIFF — audit only</a><small>{html.escape(file)}</small></td><td>Unavailable<small>No comparable HOLDOUT-DTI or organizer receipt verified for these files</small></td><td><strong>NO</strong><small>Max directional overlap {r['max_overlap']:.2%}; threshold ≤70%</small></td><td><strong>DO NOT SUBMIT</strong></td></tr>'''
    table = f'''<div class="scroll" role="region" aria-label="Historical nine-site file audit" tabindex="0"><table><thead><tr><th>Site</th><th>File to download for audit</th><th>Estimated leaderboard score</th><th>Unique among focus sites?</th><th>Submission decision</th></tr></thead><tbody>{rows}</tbody></table></div>'''
    banner = '''<div class="banner" role="status"><strong>DO NOT SUBMIT — no eligible new TIFF</strong><p>No candidate has passed all required scientific, novelty and format gates. The links below are historical comparison files, not new submissions. No manual inspection exception is needed or allowed to bypass the failed gates.</p><a class="button" href="run-card.json" download>Download negative run card</a><a class="button" href="audit.json" download>Download measured raster audit</a></div>'''
    body = f'''<div class="eyebrow">Executive decision / independent forensic audit</div><h1>Know what is safe to submit.<br>Do not spend a slot on a duplicate.</h1><p class="muted">Nine historical leaders reviewed. Byte identities verified. Score claims kept separate from measured evidence.</p>{banner}<div class="cards"><div class="card"><b>9 / 9</b>Historical leaders fail the pairwise uniqueness rule.</div><div class="card"><b>6,436</b>Dots removed from D2.8 to form the GEMSDOE32 B2 mask. No dots added.</div><div class="card"><b>0</b>Model experiments and submission slots used in this session.</div></div><h2>Which file should I submit?</h2><p><strong>None of the audited files meets your new-submission requirement.</strong> The table identifies the historical best from your supplied claims, not a verified current site champion. A prediction is not a score; no defensible leaderboard estimate is available.</p>{table}<h2>Why we stopped before generation</h2><p>The required method paragraph is missing. A registered lattice also forces at least 82.34% overlap for any 37,654 distinct dots, violating the literal 70% gate. This does not prohibit every smaller budget; it prohibits pretending this standard budget can pass. No controls were silently excluded.</p><p>Only the pinned historical subset was audited. We did not compare new surfaces, reconstruct a valid current-best out-of-fold baseline, or authenticate score receipts. <a href="research.html">Read the evidence, hypotheses and limitations →</a></p><h2>Evidence, not a live leaderboard</h2><p>This is a dated snapshot. <a href="freshness.json">Source freshness report</a> identifies changes since the source pins; it does not automatically approve newer submissions. <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard</a> and <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/data/">official competition data</a> were not accessible under this session's network allowlist.</p>'''
    (DOCS / 'index.html').write_text(page('Submission decision', body))
    guide = f'''<div class="eyebrow">Executive summary / submission guide</div><h1>A valid file is not yet an eligible submission.</h1>{banner}<h2>Nine-site summary</h2>{table}<h2>How a future file becomes eligible</h2><ol><li>Assign the missing single-method lane, authenticate cached inputs, and freeze the complete registry.</li><li>Run individual-feature leakage tests and buffered whole-segment hide-and-recover validation with the shared evaluator. Record pooled HOLDOUT-DTI, version, positives and 95% CI.</li><li>Beat the current best reconstructed on identical folds with paired uncertainty. No numeric leaderboard forecast substitutes for this.</li><li>Pass surface and final-dot registry gates without exempting controls. Exact bytes and equivalent pixel masks must both be checked.</li><li>Use the pinned shared submission writer; reopen the saved TIFF and verify one band, finite values inside the footprint in [0,1], CRS, shape and geotransform. Resolve the official outside-footprint convention; do not silently clamp broken model inputs.</li><li>The separate selector checks the live weekly cap and remaining slots. Only then may a release be labelled eligible and given a download button.</li><li>On the official submission form choose the single-band .tif (or ZIP containing only that TIFF), paste its unique name and ≤140-character note, and upload. Save the returned receipt with the exact file hash. This project has not executed this step.</li></ol><h2>Range-error prevention</h2><p>Never pass raw feature values or a no-data sentinel as prediction probabilities. The read-only format check rejects NaN/Inf inside the footprint and out-of-range values. It does not authorize an upload:</p><pre>python scripts/check_candidate.py candidate.tif --template data/sample_submission.tif</pre><p>Actual official portal acceptance is not proven by local validation. The rejected file was not provided, so its exact error cause is unknown.</p><h2>Limitations and next session</h2><p>No feature cache, authenticated receipt, matched baseline, candidate TIFF or assigned geological lane exists in this checkout. GitHub mirrors are reachable; DrivenData, Dropbox, USGS and NLR are outside the available network allowlist. See <a href="research.html">the ranked hypotheses and full next-step plan</a>. Stop after three experiments or two hours, whichever comes first.</p>'''
    (DOCS / 'executive-summary.html').write_text(page('Executive summary', guide))
    report = markdown.markdown((ROOT / 'research/REVIEW.md').read_text(), extensions=['tables', 'fenced_code'])
    (DOCS / 'research.html').write_text(page('Scientific review', report))


if __name__ == '__main__':
    build()
